-- API-only schema. No browser/service-role PostgREST access; all operations use repository ACLs.
CREATE SCHEMA IF NOT EXISTS iaapp;
CREATE TABLE iaapp.users (id uuid PRIMARY KEY, display_name text NOT NULL, handle text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE iaapp.external_identities (user_id uuid NOT NULL REFERENCES iaapp.users, issuer text NOT NULL, client_id text NOT NULL, subject text NOT NULL, PRIMARY KEY(issuer,client_id,subject));
CREATE TABLE iaapp.workspaces (id uuid PRIMARY KEY, name text NOT NULL, visibility text NOT NULL DEFAULT 'invite_only' CHECK(visibility='invite_only'));
CREATE TABLE iaapp.workspace_members (workspace_id uuid REFERENCES iaapp.workspaces, user_id uuid REFERENCES iaapp.users, role text NOT NULL CHECK(role IN ('owner','admin','member')), revoked_at timestamptz, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE iaapp.invitations (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES iaapp.workspaces, token_hash text NOT NULL UNIQUE, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), created_by uuid NOT NULL REFERENCES iaapp.users, expires_at timestamptz NOT NULL, accepted_by uuid REFERENCES iaapp.users, accepted_at timestamptz);
CREATE TABLE iaapp.participants (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES iaapp.workspaces, kind text NOT NULL CHECK(kind IN ('human','ai')), user_id uuid REFERENCES iaapp.users, owner_user_id uuid REFERENCES iaapp.users, display_name text NOT NULL, handle text NOT NULL, purpose text NOT NULL DEFAULT '', provider text, UNIQUE(id,workspace_id), UNIQUE(workspace_id,handle), CHECK((kind='human' AND user_id IS NOT NULL AND owner_user_id IS NULL AND provider IS NULL) OR (kind='ai' AND user_id IS NULL AND owner_user_id IS NOT NULL AND provider='chatgpt_work')));
CREATE UNIQUE INDEX one_human_per_workspace ON iaapp.participants(workspace_id,user_id) WHERE kind='human';
CREATE TABLE iaapp.projects (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES iaapp.workspaces, title text NOT NULL, goal text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), UNIQUE(id,workspace_id));
CREATE TABLE iaapp.project_members (project_id uuid REFERENCES iaapp.projects, user_id uuid REFERENCES iaapp.users, role text NOT NULL CHECK(role IN ('editor','reader')), revoked_at timestamptz, PRIMARY KEY(project_id,user_id));
CREATE TABLE iaapp.rooms (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES iaapp.workspaces, project_id uuid, title text NOT NULL, kind text NOT NULL CHECK(kind IN ('direct','group')), response_policy text NOT NULL CHECK(response_policy IN ('direct','mentions_only')), next_sequence bigint NOT NULL DEFAULT 0, UNIQUE(id,workspace_id), FOREIGN KEY(project_id,workspace_id) REFERENCES iaapp.projects(id,workspace_id));
CREATE TABLE iaapp.room_members (room_id uuid NOT NULL, participant_id uuid NOT NULL, workspace_id uuid NOT NULL, joined_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, left_at timestamptz, role text NOT NULL DEFAULT 'editor' CHECK(role IN ('editor','reader')), PRIMARY KEY(room_id,participant_id), FOREIGN KEY(room_id,workspace_id) REFERENCES iaapp.rooms(id,workspace_id), FOREIGN KEY(participant_id,workspace_id) REFERENCES iaapp.participants(id,workspace_id));
CREATE TABLE iaapp.connections (id uuid PRIMARY KEY, participant_id uuid NOT NULL UNIQUE REFERENCES iaapp.participants, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','awaiting_authorization','awaiting_subscription','awaiting_probe','ready','paused','expired','revoked','error')), generation integer NOT NULL DEFAULT 1 CHECK(generation>0), verified_at timestamptz, last_error_code text);
CREATE TABLE iaapp.pairing_challenges (id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES iaapp.participants, owner_user_id uuid NOT NULL REFERENCES iaapp.users, code_hash text NOT NULL UNIQUE, generation integer NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE iaapp.subscriptions (id uuid PRIMARY KEY, connection_id uuid NOT NULL REFERENCES iaapp.connections, generation integer NOT NULL, owner_user_id uuid NOT NULL REFERENCES iaapp.users, filter jsonb NOT NULL, callback_ciphertext text NOT NULL, secret_ciphertext text NOT NULL, expires_at timestamptz NOT NULL, verified_at timestamptz, revoked_at timestamptz, cursor text, UNIQUE(connection_id,generation));
CREATE TABLE iaapp.messages (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES iaapp.rooms, sender_participant_id uuid NOT NULL, workspace_id uuid NOT NULL, sequence bigint NOT NULL, body text NOT NULL CHECK(length(body)<=32000), created_at timestamptz NOT NULL DEFAULT now(), in_reply_to uuid REFERENCES iaapp.messages, attachment_ids uuid[] NOT NULL DEFAULT '{}', recipient_participant_ids uuid[] NOT NULL DEFAULT '{}', idempotency_key text NOT NULL, request_hash text NOT NULL, UNIQUE(room_id,sequence), UNIQUE(room_id,sender_participant_id,idempotency_key), UNIQUE(id,room_id), FOREIGN KEY(sender_participant_id,workspace_id) REFERENCES iaapp.participants(id,workspace_id), FOREIGN KEY(room_id,workspace_id) REFERENCES iaapp.rooms(id,workspace_id));
CREATE TABLE iaapp.attachments (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES iaapp.rooms, owner_user_id uuid NOT NULL REFERENCES iaapp.users, object_key text NOT NULL UNIQUE, file_name text NOT NULL, content_type text NOT NULL, bytes bigint NOT NULL CHECK(bytes BETWEEN 1 AND 10485760), state text NOT NULL DEFAULT 'processing' CHECK(state IN ('processing','ready','rejected')));
CREATE TABLE iaapp.deliveries (id uuid PRIMARY KEY, message_id uuid NOT NULL REFERENCES iaapp.messages, recipient_participant_id uuid NOT NULL REFERENCES iaapp.participants, connection_id uuid NOT NULL REFERENCES iaapp.connections, generation integer NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','sending','received_by_host','reply_received','failed','expired','paused','cancelled')), attempts integer NOT NULL DEFAULT 0, received_by_host_at timestamptz, response_message_id uuid REFERENCES iaapp.messages, last_error_code text, UNIQUE(message_id,recipient_participant_id,generation));
CREATE TABLE iaapp.outbox (id uuid PRIMARY KEY, delivery_id uuid NOT NULL UNIQUE REFERENCES iaapp.deliveries, event_id uuid NOT NULL UNIQUE, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, completed_at timestamptz);
CREATE INDEX outbox_pending ON iaapp.outbox(available_at) WHERE completed_at IS NULL;
CREATE TABLE iaapp.delivery_attempts (id uuid PRIMARY KEY, delivery_id uuid NOT NULL REFERENCES iaapp.deliveries, attempted_at timestamptz NOT NULL DEFAULT now(), status_code integer, error_code text);
CREATE TABLE iaapp.reply_capabilities (token_hash text PRIMARY KEY, delivery_id uuid NOT NULL REFERENCES iaapp.deliveries, connection_id uuid NOT NULL REFERENCES iaapp.connections, generation integer NOT NULL, participant_id uuid NOT NULL REFERENCES iaapp.participants, room_id uuid NOT NULL REFERENCES iaapp.rooms, expires_at timestamptz NOT NULL, consumed_at timestamptz, request_hash text, idempotency_key text);
CREATE TABLE iaapp.memory_entries (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES iaapp.workspaces, room_id uuid, project_id uuid, title text NOT NULL, body text NOT NULL, category text NOT NULL CHECK(category IN ('agreement','criterion','decision')), author_participant_id uuid NOT NULL, source_message_id uuid REFERENCES iaapp.messages, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(room_id,project_id)=1), FOREIGN KEY(room_id,workspace_id) REFERENCES iaapp.rooms(id,workspace_id), FOREIGN KEY(project_id,workspace_id) REFERENCES iaapp.projects(id,workspace_id), FOREIGN KEY(author_participant_id,workspace_id) REFERENCES iaapp.participants(id,workspace_id));
CREATE TABLE iaapp.memory_versions (entry_id uuid REFERENCES iaapp.memory_entries, version integer NOT NULL, snapshot jsonb NOT NULL, changed_by uuid NOT NULL REFERENCES iaapp.users, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(entry_id,version));
CREATE TABLE iaapp.tasks (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES iaapp.projects, title text NOT NULL, assigned_participant_id uuid REFERENCES iaapp.participants, status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','done')), version integer NOT NULL DEFAULT 1);
CREATE TABLE iaapp.audit_events (id uuid PRIMARY KEY, actor_user_id uuid REFERENCES iaapp.users, resource_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX room_members_actor ON iaapp.room_members(participant_id,room_id) WHERE left_at IS NULL;
CREATE INDEX memories_room ON iaapp.memory_entries(room_id,id);
CREATE INDEX memories_project ON iaapp.memory_entries(project_id,id);
CREATE INDEX deliveries_message ON iaapp.deliveries(message_id);
-- Default-deny on every table, even if someone later exposes the schema in PostgREST.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='iaapp' LOOP EXECUTE format('ALTER TABLE iaapp.%I ENABLE ROW LEVEL SECURITY',t.tablename); END LOOP; END $$;
REVOKE ALL ON SCHEMA iaapp FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA iaapp FROM PUBLIC;
